// replace-face: a 40 x 30 x 10 block's top replaced by a sphere of radius 50 about (20, 15, -32)
export function c005(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(40, 30) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    opSphere(context, id + "tool", { "center" : vector(20, 15, -32) * millimeter, "radius" : 50 * millimeter });
    replaceFace(context, id + "replace1", { "replaceFaces" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 15, 10) * millimeter), "templateFace" : qOwnedByBody(qBodyType(qCreatedBy(id + "tool", EntityType.BODY), BodyType.SOLID), EntityType.FACE), "oppositeSense" : false, "offset" : 0 * millimeter });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID)) };
}
